#include <vector>
#include <utility>

void bubbleSort(std::vector<int>& a) {
    for (size_t p = 0; p + 1 < a.size(); p++) {
        bool swapped = false;
        for (size_t i = 0; i + 1 < a.size() - p; i++) {
            if (a[i] > a[i + 1]) { std::swap(a[i], a[i + 1]); swapped = true; }
        }
        if (!swapped) break;   // sorted input costs one pass
    }
}

void selectionSort(std::vector<int>& a) {
    for (size_t i = 0; i + 1 < a.size(); i++) {
        size_t m = i;
        for (size_t j = i + 1; j < a.size(); j++) if (a[j] < a[m]) m = j;
        if (m != i) std::swap(a[i], a[m]);   // exactly one swap per i
    }
}

void insertionSort(std::vector<int>& a) {
    for (size_t i = 1; i < a.size(); i++) {
        int value = a[i];      // held out of the array while we shift
        size_t j = i;
        while (j > 0 && a[j - 1] > value) { a[j] = a[j - 1]; j--; }
        a[j] = value;
    }
}
